/* cppi::483cca63c4ceb8571d22a2bd806f9e659d8bb551891645d1583bd0958f2e6345 */
/* QuickSight */
SELECT ds.* FROM ( select distinct end_date from alternative_assets_dev.listed_real_assets_bloomberg_attribution_by_sector where reporting_period='QTD' and portfolio='LISTED SEG' ) ds LIMIT 0

/* cppi::59d931a89b6337968aa05a06c86ac5ca53a19514f4dd1e1557979018f309e673 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-30' and end_date = '2025-05-30')
and start_date = '2025-05-30' and end_date = '2025-05-30'

/* cppi::afac19d0e5659686869b2f52a86cd0681cf2485d54982f73afa27a06e5ff3fbe */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-09' and business_date <= date '2025-06-09' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

