/* QuickSight 31f51c18-b165-43e3-a18b-aa5923ef06b2 */
SELECT "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.workspaceid" AS "workspaceid", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.usagedate" AS "usagedate", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.clustername" AS "clustername", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.sku" AS "sku", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.dbus" AS "dbus", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.mapped_sku" AS "mapped_sku", "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.rate" AS "rate", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.account_id" AS "account_id", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.workspaceid" AS "workspaceid[workspace_map]", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.workspacename" AS "workspacename", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.project" AS "project", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.project_code" AS "project_code", "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.cost_center" AS "cost_center"
FROM (
SELECT "workspaceid" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.workspaceid", "usagedate" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.usagedate", "clustername" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.clustername", "sku" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.sku", "dbus" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.dbus", "mapped_sku" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.mapped_sku", "rate" AS "2292f0e0-a763-4875-a3b3-270b77f03ab1.rate"
FROM "PayerAwsDataCatalog"."databricks"."monthly_bill_by_workspace"
) AS "t"
LEFT JOIN (
SELECT "account_id" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.account_id", "workspaceid" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.workspaceid", "workspacename" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.workspacename", "project" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.project", "project_code" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.project_code", "cost_center" AS "0dd1163d-2d80-46ed-bc02-fa4394ac74e1.cost_center"
FROM "PayerAwsDataCatalog"."databricks"."workspace_map"
) AS "t0" ON "t"."2292f0e0-a763-4875-a3b3-270b77f03ab1.workspaceid" = "t0"."0dd1163d-2d80-46ed-bc02-fa4394ac74e1.workspaceid"

